import java.util.Scanner;

public class Main {
    static final int N = 510;
    static long[][] c = new long[N][N];
    static long[] f = new long[N];
    static long[] g = new long[N];
    static long[][] dp = new long[N][N];
    static long[][] ways = new long[N][N];
    static long[][] dp2 = new long[N][N];
    static long[][] ways2 = new long[N][N];
    static long[][] dp0 = new long[N][N];
    static long[][] ways0 = new long[N][N];

    static void add(long[] x, long y, long p) {
        for (int i = 0; i < x.length; i++) {
            x[i] = (x[i] + y) % p;
        }
    }

    static long cal(long x, long p) {
        return (x * (x - 1) / 2) % p;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int p = sc.nextInt();

        for (int i = 0; i < N; i++) {
            c[i][0] = 1;
        }
        for (int i = 1; i < N; i++) {
            for (int j = 1; j <= i; j++) {
                c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % p;
            }
        }

        f[0] = 0;
        g[0] = 1;
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                long add1 = c[i - 1][j - 1] * f[j - 1] % p * g[i - j] % p * (i + 1) % p;
                long add2 = c[i - 1][j - 1] * g[j - 1] % p * f[i - j] % p * (i + 1) % p;
                add(f, add1 + add2 + (c[i - 1][j - 1] * g[j - 1] % p * g[i - j] % p) * ((cal(j, p) + cal(i - j + 1, p)) % p), p);
                add(g, new long[]{c[i - 1][j - 1] * g[j - 1] % p * g[i - j] % p * (i + 1) % p}, p);
            }
        }

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                dp[i][j] = 0;
                ways[i][j] = 0;
                dp0[i][j] = 0;
                ways0[i][j] = 0;
                dp2[i][j] = 0;
                ways2[i][j] = 0;
            }
        }

        dp[0][0] = 0;
        ways[0][0] = 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < N; j++) {
                for (int k = 0; k < N; k++) {
                    dp2[j][k] = 0;
                    ways2[j][k] = 0;
                }
            }

            for (int j = 0; j <= Math.min(i, m); j++) {
                for (int k = 0; k <= Math.min(j, m); k++) {
                    if (k == 0) {
                        dp0[i][j] = dp[j][0];
                        ways0[i][j] = ways[j][0];
                    }
                    add(dp2[j][0], dp[j][k], p);
                    add(ways2[j][0], ways[j][k], p);
                    int rem = m - (j - k);
                    add(ways2[j + 1][k + 1], ways0[i - k][j - k] * c[rem][k + 1] % p * g[k + 1] % p, p);
                    add(dp2[j + 1][k + 1], (dp0[i - k][j - k] * c[rem][k + 1] % p * g[k + 1] % p + ways0[i - k][j - k] * c[rem][k + 1] % p * f[k + 1] % p), p);
                }
            }

            for (int j = 0; j < N; j++) {
                for (int k = 0; k < N; k++) {
                    dp[j][k] = dp2[j][k];
                    ways[j][k] = ways2[j][k];
                }
            }
        }

        long ans = 0;
        for (int i = 0; i <= m; i++) {
            ans = (ans + dp[m][i]) % p;
        }
        System.out.println(ans);
        sc.close();
    }
}

